        DatasetFilePath filePath = (ReadOnlySpan<byte> key, ulong index, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd1013v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd1013v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd1013v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd1013v)row);
        public void Dispose() => writer.Dispose();
    }
}